const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { chromium } = require("playwright");

(async () => {
  const previews = process.env.EXAMCELL_ADMIN_PREVIEW;
  if (!previews)
    throw new Error(
      "Set EXAMCELL_ADMIN_PREVIEW to the pages generated by AdminUsabilityTest.",
    );
  const root = path.resolve(__dirname, "../../public");
  const browser = await chromium.launch({ headless: true, channel: "chrome" });
  try {
    const page = await browser.newPage({
      viewport: { width: 1440, height: 1100 },
    });
    const errors = [];
    page.on("pageerror", (error) => errors.push(error.message));
    const paths = {
      "/admin/rooms": "rooms",
      "/admin/assistant": "assistant",
      "/admin/exams": "datesheet",
      "/admin/seating": "seating",
      "/admin/invigilation": "invigilation",
      "/admin/marks": "marks",
    };
    await page.route("**/*", async (route) => {
      const url = new URL(route.request().url());
      if (paths[url.pathname])
        return route.fulfill({
          contentType: "text/html",
          body: fs.readFileSync(
            path.join(previews, paths[url.pathname] + ".html"),
            "utf8",
          ),
        });
      if (url.pathname === "/ui-palette.css")
        return route.fulfill({ contentType: "text/css", body: "" });
      const file = path.resolve(root, "." + decodeURIComponent(url.pathname));
      if (
        file.startsWith(root + path.sep) &&
        fs.existsSync(file) &&
        fs.statSync(file).isFile()
      ) {
        const types = {
          ".js": "application/javascript",
          ".css": "text/css",
          ".svg": "image/svg+xml",
          ".ttf": "font/ttf",
          ".png": "image/png",
        };
        return route.fulfill({
          path: file,
          contentType: types[path.extname(file)] || "application/octet-stream",
        });
      }
      return route.fulfill({ status: 404, body: "Not found" });
    });
    for (const [url, name] of Object.entries(paths)) {
      await page.goto("http://127.0.0.1:8000" + url);
      await page.waitForSelector("#page-loading", { state: "attached" });
      const sizes = await page
        .locator(
          'main .field input:not([type="checkbox"]):not([type="hidden"]), main .field select:not([multiple]), main .field textarea',
        )
        .evaluateAll((fields) =>
          fields
            .filter(
              (field) =>
                field.getBoundingClientRect().width &&
                field.getBoundingClientRect().height,
            )
            .map((field) => ({
              name: field.name,
              height: field.getBoundingClientRect().height,
            })),
        );
      for (const field of sizes)
        assert.ok(
          Math.abs(field.height - 44) < 1,
          `${name}/${field.name}: field height ${field.height}`,
        );
      const buttons = await page.locator("main .btn").evaluateAll((buttons) =>
        buttons
          .filter(
            (button) =>
              button.getBoundingClientRect().width &&
              button.getBoundingClientRect().height,
          )
          .map((button) => ({
            label: button.textContent.trim(),
            height: button.getBoundingClientRect().height,
          })),
      );
      for (const button of buttons)
        assert.ok(
          Math.abs(button.height - 44) < 1,
          `${name}/${button.label}: button height ${button.height}`,
        );
      if (name === "rooms") {
        assert.equal(
          await page.locator("#room-layout").getAttribute("open"),
          null,
        );
        assert.equal(await page.locator(".academic-module-picker").count(), 0);
        await page.screenshot({
          path: "/private/tmp/examcell-admin-rooms-desktop.png",
          fullPage: true,
        });
      }
      if (name === "assistant") {
        const select = await page.locator("#assistant-intent").boundingBox();
        const question = await page
          .locator("#assistant-question")
          .boundingBox();
        assert.ok(
          Math.abs(select.y - question.y) < 1,
          "Assistant fields must align at the top",
        );
        assert.ok(
          Math.abs(select.width - question.width) < 1,
          "Assistant fields must have equal widths",
        );
        await page.locator(".chat-composer").screenshot({
          path: "/private/tmp/examcell-admin-assistant-fields.png",
        });
      }
      if (name === "datesheet") {
        const summary = page
          .locator("summary")
          .filter({ hasText: "Optional: allocate or adjust one paper" });
        await summary.click();
        const form = page.locator("[data-room-allocation]");
        assert.equal(await form.locator("select[multiple]").count(), 0);
        assert.equal(
          await form.locator('button[type="submit"]').isDisabled(),
          true,
        );
        await form.locator("[data-route-id]").selectOption({ index: 1 });
        await form.locator('[name="room_id"]').selectOption({ index: 1 });
        assert.equal(
          await form.locator('button[type="submit"]').isEnabled(),
          true,
        );
        await form.locator("summary").click();
        assert.ok(
          (await form.locator('input[name="extra_rooms[]"]').count()) > 0,
        );
        await form.screenshot({
          path: "/private/tmp/examcell-admin-allocation.png",
        });
      }
      await page.setViewportSize({ width: 390, height: 844 });
      await page.goto("http://127.0.0.1:8000" + url);
      await page.waitForSelector("#page-loading", { state: "attached" });
      await page.evaluate(() => document.fonts.ready);
      await page.waitForTimeout(250);
      const overflow = await page.evaluate(
        () => document.documentElement.scrollWidth - window.innerWidth,
      );
      if (overflow >= 2) {
        await page.screenshot({
          path: `/private/tmp/examcell-admin-${name}-overflow.png`,
          fullPage: true,
        });
        console.log(
          await page.locator("body *").evaluateAll((elements) =>
            elements
              .filter((element) => {
                const r = element.getBoundingClientRect();
                return (
                  r.width &&
                  r.right > window.innerWidth + 2 &&
                  getComputedStyle(element).position !== "fixed"
                );
              })
              .slice(0, 12)
              .map((element) => ({
                tag: element.tagName,
                class: element.className,
                width: element.getBoundingClientRect().width,
              })),
          ),
        );
      }
      assert.ok(
        overflow < 2,
        `${name}: horizontal page overflow ${overflow}px`,
      );
      if (name === "rooms")
        await page.screenshot({
          path: "/private/tmp/examcell-admin-rooms-mobile.png",
          fullPage: true,
        });
      await page.setViewportSize({ width: 1440, height: 1100 });
    }
    assert.deepEqual(errors, []);
    console.log(
      "PASS admin usability: six workflows, 44px fields, aligned assistant, simple rooms, guided allocation, mobile overflow, no JS errors",
    );
  } finally {
    await browser.close();
  }
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
